WITH yearly_attendance AS (
  SELECT
    Centre,
    SUM(CASE WHEN Month = 'April' THEN "Avg Daily Present" ELSE 0 END) AS April_Present,
    SUM(CASE WHEN Month = 'August' THEN "Avg Daily Present" ELSE 0 END) AS August_Present,
    SUM(CASE WHEN Month = 'December' THEN "Avg Daily Present" ELSE 0 END) AS December_Present,
    SUM(CASE WHEN Month = 'February' THEN "Avg Daily Present" ELSE 0 END) AS February_Present,
    SUM(CASE WHEN Month = 'January' THEN "Avg Daily Present" ELSE 0 END) AS January_Present,
    SUM(CASE WHEN Month = 'July' THEN "Avg Daily Present" ELSE 0 END) AS July_Present,
    SUM(CASE WHEN Month = 'June' THEN "Avg Daily Present" ELSE 0 END) AS June_Present,
    SUM(CASE WHEN Month = 'March' THEN "Avg Daily Present" ELSE 0 END) AS March_Present,
    SUM(CASE WHEN Month = 'May' THEN "Avg Daily Present" ELSE 0 END) AS May_Present,
    SUM(CASE WHEN Month = 'November' THEN "Avg Daily Present" ELSE 0 END) AS November_Present,
    SUM(CASE WHEN Month = 'October' THEN "Avg Daily Present" ELSE 0 END) AS October_Present,
    SUM(CASE WHEN Month = 'September' THEN "Avg Daily Present" ELSE 0 END) AS September_Present
  FROM "attendance_2023"
  GROUP BY Centre
)
SELECT
  Centre,
  (
    (
      (
        April_Present - April_Present
      ) / April_Present
    ) * 100
  ) AS April_Change,
  (
    (
      (
        August_Present - August_Present
      ) / August_Present
    ) * 100
  ) AS August_Change,
  (
    (
      (
        December_Present - December_Present
      ) / December_Present
    ) * 100
  ) AS December_Change,
  (
    (
      (
        February_Present - February_Present
      ) / February_Present
    ) * 100
  ) AS February_Change,
  (
    (
      (
        January_Present - January_Present
      ) / January_Present
    ) * 100
  ) AS January_Change,
  (
    (
      (
        July_Present - July_Present
      ) / July_Present
    ) * 100
  ) AS July_Change,
  (
    (
      (
        June_Present - June_Present
      ) / June_Present
    ) * 100
  ) AS June_Change,
  (
    (
      (
        March_Present - March_Present
      ) / March_Present
    ) * 100
  ) AS March_Change,
  (
    (
      (
        May_Present - May_Present
      ) / May_Present
    ) * 100
  ) AS May_Change,
  (
    (
      (
        November_Present - November_Present
      ) / November_Present
    ) * 100
  ) AS November_Change,
  (
    (
      (
        October_Present - October_Present
      ) / October_Present
    ) * 100
  ) AS October_Change,
  (
    (
      (
        September_Present - September_Present
      ) / September_Present
    ) * 100
  ) AS September_Change
FROM yearly_attendance
ORDER BY ABS(April_Change) DESC
LIMIT 1;
```
